import { showView, clearViewer } from '../atlas/viewer.js';
const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let memories=[],bag=[],lastId=null,current=null,busy=false,timer;
function phase(value){document.body.dataset.phase=value;}
function refill(){bag=memories.slice();for(let i=bag.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[bag[i],bag[j]]=[bag[j],bag[i]];}if(bag.length>1&&bag.at(-1).id===lastId)[bag[0],bag[bag.length-1]]=[bag.at(-1),bag[0]];}
function arrived(){phase('delivered');$('#receive').disabled=false;$('#receive').textContent='打开记忆盲盒 ↗';$('#parcel').disabled=false;$('#parcel-caption').textContent='一份尘封的念想，已送达';$('#invitation-title').textContent='燕子来了，带着一份从前。';$('#status').textContent='轻轻打开，看看今天与你重逢的是哪段时光。';busy=false;}
function deliver(){busy=true;phase('flying');$('#receive').disabled=true;$('#parcel').disabled=true;$('#receive').textContent='燕子正在飞来…';$('#parcel-caption').textContent='为你衔来，旧日的微光';$('#invitation-title').textContent='有一段记忆，正在归途。';$('#status').textContent='燕子从记忆池中，为你捎来一封来信。';clearTimeout(timer);timer=setTimeout(arrived,reduced?0:2600);}
function openParcel(){if(busy||!memories.length||document.body.dataset.phase!=='delivered')return;busy=true;if(!bag.length)refill();current=bag.pop();lastId=current.id;phase('opening');$('#receive').disabled=true;$('#parcel').disabled=true;$('#parcel-caption').textContent='原来，是这段时光。';$('#memory-name').textContent=current.name||'未命名的记忆';const date=new Date(current.created_at*1000);$('#memory-meta').textContent=`${Number.isFinite(date.getTime())?date.toLocaleDateString('zh-CN')+' 珍藏 · ':''}${current.mode==='world'?'一处旧日空间':'一件立体念想'}`;$('#another').hidden=memories.length<2;timer=setTimeout(()=>{$('#reveal').showModal();showView(current,'3d').catch(()=>{$('#viewer-status').textContent='立体记忆暂时无法打开，可以切换到原照片。';});busy=false;$('#receive').textContent='再等一只燕子 ↗';$('#status').textContent='念想已送达。愿这次重逢，照亮你的一瞬。';},reduced?0:900);}
$('#receive').onclick=()=>{const state=document.body.dataset.phase;if(state==='error')load();else if(state==='delivered')openParcel();else deliver();};$('#parcel').onclick=openParcel;
$('#close-reveal').onclick=()=>$('#reveal').close();$('#reveal').addEventListener('close',()=>{clearViewer();if(!busy){$('#receive').disabled=false;$('#receive').focus();}});
$('#another').onclick=()=>{$('#reveal').close();deliver();};
$('#view-photo').onclick=()=>showView(current,'photo');$('#view-3d').onclick=()=>showView(current,'3d').catch(()=>{$('#viewer-status').textContent='立体记忆暂时无法打开，可以切换到原照片。';});
$('#about').onclick=()=>{const open=$('#about').getAttribute('aria-expanded')!=='true';$('#about').setAttribute('aria-expanded',String(open));$('#about-copy').hidden=!open;};
async function load(){busy=true;$('#receive').disabled=true;phase('loading');try{const response=await fetch('/api/memories',{signal:AbortSignal.timeout(15000),cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();memories=data.items.filter(m=>m.status==='ready'&&!m.experimental&&(m.mode==='world'?m.world_assets?.splat_url:m.mode!=='fourview'&&m.model_url));if(!memories.length){phase('empty');$('#invitation-title').textContent='先珍藏，才有意外的重逢。';$('#status').textContent='记忆池里还没有已生成的立体记忆。去第一章生成一件物件或一处空间，燕子便有了归来的理由。';$('#parcel-caption').textContent='等一段值得捎回的时光';$('#receive').hidden=true;$('#empty-link').hidden=false;busy=false;return;}$('#pool-note').textContent=`${memories.length} 段已生成的记忆 · ${memories.length>1?'每轮不重复，直到再次相逢':'等待与你重逢'}`;refill();deliver();}catch{phase('error');busy=false;$('#invitation-title').textContent='归途偶有风，稍等便好。';$('#status').textContent='暂时无法读取记忆池，请确认本地服务已启动后重试。';$('#receive').disabled=false;$('#receive').textContent='重新等候信使 ↗';}}
addEventListener('pagehide',()=>{clearTimeout(timer);clearViewer();});addEventListener('pageshow',e=>{if(e.persisted)location.reload();});load();
